-- Foundation migration. Generated by drizzle-kit, then extended by hand with
-- the four things it cannot express: extensions, FORCE ROW LEVEL SECURITY,
-- grants, and the append-only privilege on atom_events. Those additions are
-- at the foot of the file, under "Hand-written".
--
-- The `vector` extension is created with no vector column yet. It costs
-- nothing and proves pgvector is available on the host today, rather than
-- discovering in phase 1 that the retrieval design does not run where the
-- database lives.
CREATE EXTENSION IF NOT EXISTS "vector";--> statement-breakpoint
CREATE EXTENSION IF NOT EXISTS "pg_trgm";--> statement-breakpoint
CREATE TYPE "public"."actor_kind" AS ENUM('human', 'agent');--> statement-breakpoint
CREATE TYPE "public"."atom_event" AS ENUM('proposed', 'ratified', 'rejected', 'superseded');--> statement-breakpoint
