CREATE TYPE "public"."atom_status" AS ENUM('provisional', 'canonical', 'rejected', 'superseded');--> statement-breakpoint
DO $$ BEGIN
	CREATE ROLE "standfast_app" NOLOGIN NOBYPASSRLS;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
