-- ─── Hand-written: what drizzle-kit cannot express ───────────────────────
--
-- FORCE, not just ENABLE. Without FORCE the table owner bypasses every
-- policy silently, so a test suite connecting as the owner passes while
-- protecting nothing. schema-guards.integration.test.ts asserts this on
-- every table, because omitting it is invisible until it matters.
ALTER TABLE "orgs" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "actors" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "api_keys" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
