ALTER TABLE "atoms" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "atom_events" FORCE ROW LEVEL SECURITY;--> statement-breakpoint

-- A policy restricts which rows a role may touch. It does not grant the
-- privilege to touch the table at all — that is a separate thing, and
-- forgetting it produces a permission error rather than a silent hole.
GRANT USAGE ON SCHEMA "public" TO "standfast_app";--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "orgs" TO "standfast_app";--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "actors" TO "standfast_app";--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "api_keys" TO "standfast_app";--> statement-breakpoint
