GRANT SELECT, INSERT, UPDATE, DELETE ON "document_sections" TO "standfast_app";--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE, DELETE ON "atoms" TO "standfast_app";--> statement-breakpoint

-- atom_events is append-only, and that is a privilege rather than a
-- convention: no UPDATE, no DELETE. Ratification throughput is a product
-- metric, and a metric whose history can be rewritten is not evidence.
GRANT SELECT, INSERT ON "atom_events" TO "standfast_app";
